-- Migration 0025 — `inbound_messages`, the reply-evidence table (MSG-03, Phase 4).
--
-- GENERATED by drizzle-kit from src/db/schema/inbound-messages.ts, then renamed
-- from its random tag (`0025_last_the_watchers`), RE-STAMPED in
-- meta/_journal.json, EDITED to remove three statements the generator emitted
-- against `cadences`, and hand-extended with the GRANT block. Every one of those
-- four edits is required; the reasons are below.
--
-- ── WHY THE `cadences` STATEMENTS WERE DELETED (and they were not optional) ──
--
-- The generator emitted, unasked:
--
--   DROP INDEX "cadences_one_per_opened_event";
--   CREATE UNIQUE INDEX "cadences_one_live_per_job" ON "cadences" ...;
--   CREATE UNIQUE INDEX "cadences_one_per_opened_event" ON "cadences" ...;
--
-- Not because the schema changed — it did not. Migrations 0023 and 0024 are
-- HAND-WRITTEN (they narrow and add those indexes), so the drizzle snapshot did
-- not know about them and the generator treated the difference as new work.
--
-- Applying it would have FAILED and, worse, failed halfway. `CREATE UNIQUE INDEX
-- cadences_one_live_per_job` has no `IF NOT EXISTS`, the index already exists
-- (verified against the production database: `cadences_one_live_per_job` and
-- `cadences_one_per_opened_event` are both present, with exactly the definitions
-- above), so Postgres raises 42P07 — AFTER the DROP has already run. The
-- statement-breakpoint boundary means the drop is not rolled back with it. Net
-- effect: `cadences_one_per_opened_event` gone, the G-3-2 replay guarantee
-- silently off, and `migrate` reporting a failure that names an unrelated index.
--
-- The 0025 SNAPSHOT still records all three indexes correctly, which is what
-- stops the next `db:generate` from re-emitting them. The statements are the
-- drift; the snapshot is the fix.
--
-- ── WHY THE GRANTS ARE HAND-APPENDED (the fifth restatement of 0003's rule) ──
--
-- drizzle-kit models tables and policies. It does not model GRANTs, and Postgres
-- checks PRIVILEGES BEFORE ROW-LEVEL SECURITY: a table with a perfect policy and
-- no grant returns `42501 permission denied` — an ERROR rather than an empty
-- result — which leaks the table's existence and breaks the property that
-- denial and absence are indistinguishable.
--
-- REVOKE-THEN-GRANT, following 0005/0007/0011/0017. Hosted Supabase installs
-- ALTER DEFAULT PRIVILEGES at bootstrap and silently hands anon and
-- authenticated the full set — including TRUNCATE, WHICH IS NOT SUBJECT TO RLS,
-- so no policy test could ever catch it. A fresh `supabase start` database (what
-- CI runs) has no such default, so skipping the REVOKE makes CI and production
-- disagree with production being the permissive one.

CREATE TABLE "inbound_messages" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"tenant_id" uuid,
	"cadence_id" uuid,
	"quote_id" uuid,
	"channel" text DEFAULT 'sms' NOT NULL,
	"from_address" text NOT NULL,
	"normalized_from" text,
	"to_address" text,
	"body" text DEFAULT '' NOT NULL,
	"provider_message_id" text,
	"is_stop" boolean DEFAULT false NOT NULL,
	"attribution" text NOT NULL,
	"matched_cadence_count" smallint DEFAULT 0 NOT NULL,
	"candidate_tenant_ids" uuid[],
	"raw_payload" jsonb,
	"triaged_at" timestamp with time zone,
	"received_at" timestamp with time zone DEFAULT now() NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "inbound_messages_attribution_known" CHECK (attribution IN ('threaded', 'ambiguous', 'unmatched', 'dead_letter'))
);
--> statement-breakpoint
ALTER TABLE "inbound_messages" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE INDEX "inbound_messages_normalized_from_idx" ON "inbound_messages" USING btree ("normalized_from");--> statement-breakpoint
CREATE POLICY "inbound_messages_member_or_operator_access" ON "inbound_messages" AS PERMISSIVE FOR ALL TO "authenticated" USING ((tenant_id IS NOT NULL AND has_tenant_access(tenant_id)) OR (tenant_id IS NULL AND is_operator())) WITH CHECK ((tenant_id IS NOT NULL AND has_tenant_access(tenant_id)) OR (tenant_id IS NULL AND is_operator()));--> statement-breakpoint

-- ── TABLE PRIVILEGES ────────────────────────────────────────────────────────

REVOKE ALL ON public.inbound_messages FROM anon;
--> statement-breakpoint
REVOKE ALL ON public.inbound_messages FROM authenticated;
--> statement-breakpoint

-- READ-ONLY TO `authenticated`, exactly like the six cadence tables (0017).
--
-- The triage screen plan 04-06 builds performs ONE write to this table — setting
-- `triaged_at` — and even that is a server action running through the
-- service-role repository, for the reason 0017 states about every D-16 control:
-- an operator marking a reply handled is one step of a decision, and the console
-- role holding a direct UPDATE grant is the console role holding the ability to
-- perform a third of it.
--
-- An INSERT grant is the one that matters most here. This table is COMPLIANCE
-- EVIDENCE: `is_stop`, `attribution` and `received_at` are what answers "did we
-- honour that STOP, and when did we know". A console-writable insert path is a
-- path by which that record can be fabricated after the fact, which would make
-- the whole table worthless as evidence of anything. A DELETE grant is worse
-- still — it removes the record of a customer having asked us to stop.
--
-- anon gets SELECT so an unauthenticated read returns `[]` rather than 42501;
-- the policy above then returns zero rows, because `has_tenant_access()` admits
-- nothing for an anonymous JWT and `is_operator()` admits nothing for a user who
-- is not on the allowlist.
GRANT SELECT ON public.inbound_messages TO anon;
--> statement-breakpoint
GRANT SELECT ON public.inbound_messages TO authenticated;
--> statement-breakpoint
GRANT ALL ON public.inbound_messages TO service_role;
